import sys
p=sys.argv[1]; s=open(p).read()
add='''    # security: nothing uploaded or cached is ever run as PHP; no backup/source copies served
    location ~* ^/wp-content/(uploads|cache)/.*\\.(php\\d?|phtml|phar|pht)(/|$) {
        deny all;
    }
    location ~* \\.(bak|orig|save|swp|old|sql|md)$ {
        deny all;
    }
'''
marker='    location ~ \\.php$ {'
assert marker in s and 'security: nothing uploaded' not in s
s=s.replace(marker, add+marker,1)
open(p,'w').write(s)
EOF
